INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.LWF', 'IN-TN', '2026-v2', '2026-04-01', NULL, '{"kind":"lwf","months":[12],"employee":"20","employer":"40","minDaysEmployed":30}', 'Tamil Nadu Labour Welfare Fund Act 1972 as applied by the Board (G.O. No. 161 of 02.12.2022): 20 employee / 40 employer a year in December, for people employed 30 days or more (review M3). Managers and supervisors above 15,000 a month are not yet excluded (needs a role on the person; CA).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, employed long enough: 20 / 40', 'lwf', '{"month":12,"daysEmployed":200}', '{"employee":"20","employer":"40"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December, employed 29 days: none', 'lwf', '{"month":12,"daysEmployed":29}', '{"employee":"0","employer":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.LWF' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
